MATCH (p:Painting)
WHERE EXISTS {
  MATCH (p)-[:hasGenre]->(g:Genre)
  WHERE toLower(g.name) CONTAINS 'portrait' 
    OR any(alias IN g.aliases WHERE toLower(alias) CONTAINS 'portrait')
}
OR EXISTS {
  MATCH (p)-[:associatedWith]->(a:ArtMovement)
  WHERE toLower(a.name) CONTAINS 'academic art' 
    OR any(alias IN a.aliases WHERE toLower(alias) CONTAINS 'academic art')
}
RETURN count(DISTINCT p) AS number_of_paintings
